// ---- v6: CSR write-mask gating, minimal (mcache_ctl only) ----------------
// With HYBRID_FLAG_WRITE_MASK set, mcache_ctl is restored ONLY when the
// producer's guest actually WROTE it (its mask bit set). An untouched
// mcache_ctl's drained value is just the producer's reset default, so
// restoring it would clobber the engine's OWN reset value. This prototype
// gates only mcache_ctl; mmisc_ctl (and the Andes/M-ext blocks) stay ungated
// until the completion commit.
TEST_CASE("v6 minimal: an unwritten mcache_ctl is skipped, mmisc_ctl still restored")
{
  auto restores = [](bool set_mcache_bit, uint16_t csr) {
    RecordingBus bus;
    bus.dmstatus_value = (1u << 9) | (1u << 17);
    auto s = rv64_state(0x80001000, 0);
    s.flags |= HYBRID_FLAG_WRITE_MASK;
    s.mcache_ctl = 0x703ULL;  // I/D-cache enable: non-zero so a restore shows
    s.mmisc_ctl  = 0x40ULL;
    if (set_mcache_bit)
      hybrid_wm_set(s.write_mask, HYBRID_WM_MCACHE_CTL);
    hybrid::ResumeDriver driver(bus);
    driver.resume(s);
    return contains_regno(cmd_regnos(bus.ops), hybrid::regno_csr(csr));
  };

  CHECK_FALSE(restores(/*set_mcache_bit=*/false, 0x7CA));  // unwritten -> skipped
  CHECK(restores(/*set_mcache_bit=*/true, 0x7CA));         // written  -> restored
  CHECK(restores(/*set_mcache_bit=*/false, 0x7D0));        // mmisc_ctl ungated
}

